434	    /// Find the current option index for the selected setting
435	    fn current_option_index(&self, config: &Config) -> usize {
436	        let options = self.get_options(config);
437	        options
438	            .iter()
439	            .position(|(_, selected)| *selected)
440	            .unwrap_or(0)
441	    }
