1	//! Screen controllers for the application.
2	//!
3	//! This module provides screen controllers that implement the `Screen` trait.
4	//! Each screen controller owns its state and handles both rendering and events.
5	//!
6	//! # Architecture
7	//!
8	//! ```text
9	//! ┌────────────────────────────────────────────────────────┐
10	//! │                      App                                │
11	//! │  ┌────────────────────────────────────────────────┐    │
12	//! │  │               Screen Router                     │    │
13	//! │  │  match current_screen {                         │    │
14	//! │  │    MainMenu => main_menu.handle_event(...)     │    │
15	//! │  │    StorageSetup => storage_setup.handle_event(...) │    │
16	//! │  │    ...                                          │    │
17	//! │  │  }                                              │    │
18	//! │  └────────────────────────────────────────────────┘    │
19	//! │                                                         │
20	//! │  ┌────────────────────────────────────────────────┐    │
21	//! │  │               Screen Trait                      │    │
22	//! │  │  - render(frame, area, context)                │    │
23	//! │  │  - handle_event(event, context) -> Action      │    │
24	//! │  │  - is_input_focused() -> bool                  │    │
25	//! │  └────────────────────────────────────────────────┘    │
26	//! └────────────────────────────────────────────────────────┘
27	//! ```
28	//!
29	//! # Example
30	//!
31	//! ```rust,ignore
32	//! use crate::screens::{Screen, ScreenContext, ScreenAction};
33	//!
34	//! struct MyScreen {
35	//!     state: MyScreenState,
36	//! }
37	//!
38	//! impl Screen for MyScreen {
39	//!     fn render(&mut self, frame: &mut Frame, area: Rect, ctx: &ScreenContext) -> Result<()> {
40	//!         // Render the screen
41	//!         Ok(())
42	//!     }
43	//!
44	//!     fn handle_event(&mut self, event: Event, ctx: &mut ScreenContext) -> Result<ScreenAction> {
45	//!         // Handle events and return navigation action
46	//!         Ok(ScreenAction::None)
47	//!     }
48	//! }
49	//! ```
