184	pub struct StorageSetupScreen {
185	    state: StorageSetupState,
186	    /// Clickable regions for method menu items
187	    method_regions: MouseRegions<usize>,
188	    /// Area of the method list pane (for scroll hit-testing)
189	    method_pane_area: Option<Rect>,
190	    /// Clickable regions for form fields
191	    form_field_regions: MouseRegions<usize>,
192	}
193	
194	impl Default for StorageSetupScreen {
195	    fn default() -> Self {
196	        Self::new()
197	    }
198	}
