200	impl StorageSetupScreen {
201	    #[must_use]
202	    pub fn new() -> Self {
203	        Self {
204	            state: StorageSetupState::default(),
205	            method_regions: MouseRegions::new(),
206	            method_pane_area: None,
207	            form_field_regions: MouseRegions::new(),
208	        }
209	    }
210	
211	    /// Reset the screen state
212	    pub fn reset(&mut self) {
213	        self.state = StorageSetupState::default();
214	    }
215	
216	    /// Check if the async setup step needs processing.
217	    /// Returns true if there's a setup step in progress that needs ticking.
218	    #[must_use]
219	    pub fn needs_tick(&self) -> bool {
220	        matches!(self.state.step, StorageSetupStep::Processing(_))
221	    }
222	
223	    /// Get the current state (read-only).
224	    #[must_use]
225	    pub fn get_state(&self) -> &StorageSetupState {
226	        &self.state
227	    }
228	
229	    /// Get mutable state.
230	    pub fn get_state_mut(&mut self) -> &mut StorageSetupState {
231	        &mut self.state
232	    }
233	
234	    /// Get icons from config
235	    fn icons(&self, ctx: &RenderContext) -> Icons {
236	        Icons::from_config(ctx.config)
237	    }
238	
239	    /// Get key display for an action
240	    fn key_display(&self, ctx: &RenderContext, action: Action) -> String {
241	        ctx.config.keymap.get_key_display_for_action(action)
242	    }
243	
244	    /// Render the method selection menu (left pane)
245	    fn render_method_list(&mut self, frame: &mut Frame, area: Rect, ctx: &RenderContext) {
246	        let t = theme();
247	        let icons = self.icons(ctx);
248	        let is_focused = self.state.focus == StorageSetupFocus::MethodList;
249	
250	        // Store pane area for mouse
251	        self.method_pane_area = Some(area);
252	
253	        // Build menu items
254	        let items: Vec<MenuItem> = StorageMethod::all()
255	            .iter()
256	            .map(|method| {
257	                let (icon, text, color) = match method {
258	                    StorageMethod::GitHub => (icons.github(), "GitHub Repository", t.success),
259	                    StorageMethod::Local => (icons.folder(), "Local Repository", t.tertiary),
260	                };
261	                MenuItem::new(icon, text, color)
262	            })
263	            .collect();
264	
265	        // Create bordered container
266	        let border_style = if is_focused {
267	            focused_border_style()
268	        } else {
269	            unfocused_border_style()
270	        };
271	
272	        let block = Block::default()
273	            .borders(Borders::ALL)
274	            .title(" Storage Method ")
275	            .title_alignment(Alignment::Center)
276	            .border_type(t.border_type(is_focused))
277	            .border_style(border_style)
278	            .style(t.background_style());
279	
280	        let inner = block.inner(area);
281	        frame.render_widget(block, area);
282	
283	        // Render menu and store clickable areas
284	        let menu = Menu::new(items);
