904	    /// Handle events when method list is focused
905	    fn handle_list_event(&mut self, action: Option<Action>) -> Result<ScreenAction> {
906	        if let Some(action) = action {
907	            match action {
908	                Action::MoveUp => {
909	                    let current = self.state.method.index();
910	                    if current > 0 {
911	                        self.state.method = StorageMethod::from_index(current - 1).unwrap();
912	                        self.state.menu_state.select(Some(current - 1));
913	                    }
914	                }
915	                Action::MoveDown => {
916	                    let current = self.state.method.index();
917	                    if current < StorageMethod::all().len() - 1 {
918	                        self.state.method = StorageMethod::from_index(current + 1).unwrap();
919	                        self.state.menu_state.select(Some(current + 1));
920	                    }
921	                }
922	                Action::Confirm | Action::NextTab | Action::MoveRight => {
923	                    self.state.focus = StorageSetupFocus::Form;
924	                }
925	                Action::Cancel | Action::Quit => {
926	                    self.reset();
927	                    return Ok(ScreenAction::Navigate(crate::ui::Screen::MainMenu));
928	                }
