1110	    /// Handle Local form input (character input handled at top of `handle_form_event`)
1111	    fn handle_local_form_input(&mut self, action: Option<Action>) -> Result<ScreenAction> {
1112	        // PrevTab (Shift+Tab) goes back to menu
1113	        if let Some(Action::PrevTab) = action {
1114	            self.state.focus = StorageSetupFocus::MethodList;
1115	            return Ok(ScreenAction::None);
1116	        }
1117	
1118	        // Don't allow input on disabled fields (character input handled at top of handle_form_event)
1119	        if self.state.is_reconfiguring {
1120	            return Ok(ScreenAction::None);
1121	        }
1122	
1123	        let input = &mut self.state.local_path_input;
1124	
1125	        // Handle text editing actions
1126	        if let Some(act) = action {
1127	            match act {
1128	                Action::Backspace => input.backspace(),
1129	                Action::DeleteChar => input.delete(),
1130	                Action::MoveLeft => input.move_left(),
1131	                Action::MoveRight => input.move_right(),
1132	                Action::Home => input.move_home(),
1133	                Action::End => input.move_end(),
1134	                _ => {}
1135	            }
1136	        }
1137	
1138	        Ok(ScreenAction::None)
