1434	    fn on_enter(&mut self, ctx: &ScreenContext) -> Result<()> {
1435	        // Check if already configured using the proper method
1436	        // This checks: GitHub mode with github config, OR Local mode with .git existing
1437	        let is_configured = ctx.config.is_repo_configured();
1438	
1439	        if is_configured {
1440	            // Reconfiguration mode - pre-fill with existing values
1441	            self.state.is_reconfiguring = true;
1442	            self.state.focus = StorageSetupFocus::MethodList;
1443	
1444	            // Determine which method was used
1445	            if ctx.config.github.is_some() {
1446	                // GitHub mode
1447	                self.state.method = StorageMethod::GitHub;
1448	                self.state.menu_state.select(Some(0));
1449	
1450	                if let Some(ref github) = ctx.config.github {
1451	                    // Pre-fill token (masked display - actual token not shown)
1452	                    if github.token.is_some() {
1453	                        self.state.token_input = TextInput::with_text("••••••••••••••••••••");
1454	                    }
1455	                    // Pre-fill repo name
1456	                    self.state.repo_name_input = TextInput::with_text(github.repo.clone());
1457	                }
1458	                // Ensure edit mode is off
1459	                self.state.is_editing_token = false;
1460	                // Pre-fill repo path
1461	                self.state.repo_path_input =
1462	                    TextInput::with_text(ctx.config.repo_path.to_string_lossy().to_string());
1463	            } else {
1464	                // Local mode
1465	                self.state.method = StorageMethod::Local;
1466	                self.state.menu_state.select(Some(1));
1467	                self.state.local_path_input =
1468	                    TextInput::with_text(ctx.config.repo_path.to_string_lossy().to_string());
1469	            }
1470	
1471	            self.state.error_message = None;
1472	            self.state.status_message = None;
1473	            self.state.step = StorageSetupStep::Input;
1474	            self.state.setup_data = None;
1475	        } else {
1476	            // Fresh setup - reset to defaults
1477	            self.reset();
1478	        }
1479	        Ok(())
1480	    }
