#[cfg(test)]
mod tests {
    use super::*;
    use std::path::PathBuf;

    fn test_config() -> Config {
        Config {
            repo_path: PathBuf::from("/tmp/test-repo"),
            ..Default::default()
        }
    }

    #[test]
    fn test_setting_item_names() {
        assert_eq!(SettingItem::Theme.name(), "Theme");
        assert_eq!(SettingItem::IconSet.name(), "Icon Set");
        assert_eq!(SettingItem::KeymapPreset.name(), "Keymap Preset");
        assert_eq!(SettingItem::Backups.name(), "Backups");
        assert_eq!(SettingItem::CheckForUpdates.name(), "Automatic Update Checks");
        assert_eq!(SettingItem::EmbedCredentials.name(), "Token in Remote URL");
    }

    #[test]
    fn test_check_for_updates_label_renamed() {
        let item = SettingItem::CheckForUpdates;
        assert_eq!(item.name(), "Automatic Update Checks");
        assert_ne!(item.name(), "Check for Updates");
    }

    #[test]
    fn test_setting_item_all_includes_check_for_updates() {
        let items = SettingItem::all(RepoMode::Local);
        assert!(items.contains(&SettingItem::CheckForUpdates));
    }

    #[test]
    fn test_setting_item_from_index() {
        let items = SettingItem::all(RepoMode::Local);
        let check_updates_idx = items
            .iter()
            .position(|&item| item == SettingItem::CheckForUpdates)
            .unwrap();
        assert_eq!(
            SettingItem::from_index(check_updates_idx, RepoMode::Local),
            Some(SettingItem::CheckForUpdates)
        );
    }

    #[test]
    fn test_settings_screen_creation() {
        let screen = SettingsScreen::new();
        assert_eq!(screen.state.focus, SettingsFocus::List);
        assert_eq!(screen.state.option_index, 0);
    }

    #[test]
    fn test_settings_state_default() {
        let state = SettingsState::default();
        assert_eq!(state.focus, SettingsFocus::List);
        assert_eq!(state.option_index, 0);
        assert_eq!(state.list_state.selected(), Some(0));
    }

    #[test]
    fn test_apply_setting_automatic_update_checks_enabled() {
        let mut config = test_config();
        config.updates.check_enabled = false;

        let screen = SettingsScreen::new();
        let result =
            screen.apply_setting_to_config(&mut config, "Automatic Update Checks", 0);

        assert!(result);
        assert!(config.updates.check_enabled);
    }

    #[test]
    fn test_apply_setting_automatic_update_checks_disabled() {
        let mut config = test_config();
        config.updates.check_enabled = true;

        let screen = SettingsScreen::new();
        let result =
            screen.apply_setting_to_config(&mut config, "Automatic Update Checks", 1);

        assert!(result);
        assert!(!config.updates.check_enabled);
    }

    #[test]
    fn test_get_options_check_for_updates() {
        let config = test_config();
        let screen = SettingsScreen::new();

        let config_enabled = {
            let mut c = config.clone();
            c.updates.check_enabled = true;
            c
        };
        let options_enabled = screen.get_options(&config_enabled);
        assert_eq!(options_enabled.len(), 2);
        assert_eq!(options_enabled[0], ("Enabled".to_string(), true));
        assert_eq!(options_enabled[1], ("Disabled".to_string(), false));

        let config_disabled = {
            let mut c = config;
            c.updates.check_enabled = false;
            c
        };
        let options_disabled = screen.get_options(&config_disabled);
        assert_eq!(options_disabled.len(), 2);
        assert_eq!(options_disabled[0], ("Enabled".to_string(), false));
        assert_eq!(options_disabled[1], ("Disabled".to_string(), true));
    }

    #[test]
    fn test_setting_behavior_unchanged() {
        let mut config = test_config();
        config.updates.check_enabled = false;

        let screen = SettingsScreen::new();
        screen.apply_setting_to_config(&mut config, "Automatic Update Checks", 0);
        assert!(config.updates.check_enabled);

        screen.apply_setting_to_config(&mut config, "Automatic Update Checks", 1);
        assert!(!config.updates.check_enabled);
    }

    #[test]
    fn test_other_settings_unaffected() {
        let mut config = test_config();
        let original_theme = config.theme.clone();
        let original_icon_set = config.icon_set.clone();

        let screen = SettingsScreen::new();
        screen.apply_setting_to_config(&mut config, "Automatic Update Checks", 0);

        assert_eq!(config.theme, original_theme);
        assert_eq!(config.icon_set, original_icon_set);
    }
}

